{
  "findings": [
    {
      "check_id": "CKV_GCP_62",
      "title": "Ensure GCS buckets have uniform bucket-level access enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have uniform bucket-level access enabled, which can lead to inconsistent access control."
    }
  ],
  "patched_code": "resource "google_storage_bucket" "compliance_storage" {
  name     = "${var.project_id}-digital-asset-trading-platform-compliance"
  location = var.region
  versioning {
    enabled = true
  }
  uniform_bucket_level_access = true
  lifecycle_rule {
    condition {
      age = 2555
    }
    action {
      type = "Delete"
    }
  }
}",
  "fix_summary": "Enabled uniform bucket-level access on the GCS bucket to ensure consistent access control."
}
